//! Pressable: a clickable, focusable root with no look of its own and a children slot.
//!
//! `W.Button` is a finished control: ControlShell frame, tone, size-tier padding / min height and a
//! centered icon + label. Rows whose content is the caller's (icon + title + subtitle + trailing
//! chevron: navigation rows, overview rows, list items) need the button semantics without that
//! geometry. Pressable gives exactly the semantics:
//!
//!   root (row, tag .button; focusable; a11y role button; the children slot)
//!
//! - click: `onClick`, suppressed while `disabled`; Space / Enter on the focused root synthesize
//!   it (tag .button);
//! - keyboard focus: in the Tab order unless disabled; `focusRing` (null = no ring);
//! - state: `disabled` / `selected` / `expanded` feed the root's style conditions and a11y; hover /
//!   pressed / focus are driven by the node itself;
//! - look: none by default (no padding, gap, radius, background or min height; children are laid
//!   out in a row with centered cross axis). Give it with `look` — the same `ui.view.Look` as
//!   `W.Button`'s: a YSS style / recipe / parameterized style (or a tuple / source of one), resolved
//!   against the current theme on every restyle (token colors follow a theme switch, nothing to
//!   replay by hand) and per state against this root's own disabled / selected / expanded and the
//!   node-driven hover / active / focus. Division of labour with the element's `style` overlay:
//!   `look` = the row's own per-state look from tokens / recipes; the overlay = transitions,
//!   layout, and looks driven by the caller's state (`state` on the element) or by runtime values
//!   that are not tokens — it sits above every state layer;
//! - cursor: pointer, `not-allowed` while disabled (defaults under the look: a look that writes
//!   `cursor` in its base changes the enabled cursor; the disabled one only through its own
//!   `:disabled` block, as on Button).
//!
//! `test_id` / `style` / `visible` written on the element land on this root, the node that is
//! clickable and carries the state (the Badge lesson in docs/YIX_COMPONENTS.md).
//!
//! Yix: `<W.Pressable testId="nav.general" selected={on} onClick={pick(1)}><icon …/><text>…</text></W.Pressable>`.
//! Zig: `ui.view.with(W.Pressable(.{ .on_click = h }), .{ … })`.
//!
//! Hand-written Zig (not `.yix`): the root's click gate, cursor and a11y are a handful of lines,
//! and the component stays out of the LP3 template-equivalence fixtures (whose goldens are
//! regenerated by a separate reviewed step).
const std = @import("std");
const core = @import("../../core.zig");
const ui = @import("../../ui.zig");
const v = @import("../../view.zig");
const reactive = @import("../../reactive.zig");
const Scope = reactive.Scope;
const Source = reactive.Source;
const Cx = core.Cx;
const Node = core.Node;
const ConditionalStyle = core.ConditionalStyle;

pub const PressableProps = struct {
    disabled: Source(bool) = .{ .value = false },
    selected: Source(bool) = .{ .value = false },
    expanded: Source(bool) = .{ .value = false },
    on_click: ?ui.Handler(void) = null,
    /// Keyboard focus ring; null = none (whether there is one is fixed at mount).
    focus_ring: Source(?ui.FocusRingConfig) = .{ .value = .{} },
    /// Accessible name; empty = taken from the content's text.
    a11y_label: Source([]const u8) = .{ .value = "" },
    /// Accessible description (details read after the name); empty = none.
    a11y_description: Source([]const u8) = .{ .value = "" },
    /// Per-state look of the root (Yix `look={S.Row}`, Zig `.look = S.Row` / `S.Row.of(.{ … })`):
    /// a YSS style / recipe / parameterized style, a tuple of those or a source of one
    /// (`ui.view.Look`, converted by the props). Resolved against the current theme on every
    /// restyle and per state against this root's own disabled / selected / expanded and the
    /// node-driven hover / active / focus. Concrete per-state values (a ConditionalStyle) are not
    /// taken: write them as a YSS style, or put runtime values on the element's `style` overlay.
    look: Source(v.Look) = .{ .value = .{} },
};

/// `W.Pressable(.{ … })` (props as in `PressableProps`; signals allowed). Children go in with
/// `ui.view.with` (Yix: tag children).
pub fn Pressable(args: anytype) v.SlottedOf(mountPressable) {
    comptime checkLookArg(@TypeOf(args));
    return v.slotted(mountPressable, reactive.props.coerce(PressableProps, args));
}

/// A ConditionalStyle `look` (or a source / signal of one) gets a Pressable-specific migration
/// message instead of the generic Look error (which names Button's concrete parameters).
fn checkLookArg(comptime A: type) void {
    if (@typeInfo(A) != .@"struct" or !@hasField(A, "look")) return;
    const L = @FieldType(A, "look");
    const value = if (comptime @import("../../reactive/source.zig").reactiveKindOf(L) != null or (@typeInfo(L) == .@"union" and @hasDecl(L, "zenit_source"))) reactive.SourceValueOf(L) else L;
    if (value == ConditionalStyle)
        @compileError("W.Pressable: `look` takes a YSS style / recipe (ui.view.Look), resolved against the theme per state; write the per-state values as a YSS style (`:hover { … }`), or put runtime (non-token) values on the element's `style` overlay with `state`");
}

/// Default layout and cursor: a row with a centered cross axis; pointer, not-allowed while
/// disabled. A recipe (not a plain style) so the look merges per state into it and every state
/// source is wired on the root.
const Root = ui.cva(.{ .base = .{ .direction = .row, .align_items = .center, .cursor = .pointer, ._disabled = .{ .cursor = .not_allowed } } });

fn a11yOf(name: []const u8, description: []const u8, disabled: bool, selected: bool, expanded: bool) core.A11yProps {
    return .{ .role = .button, .label = if (name.len > 0) name else null, .description = if (description.len > 0) description else null, .disabled = disabled, .selected = selected, .expanded = expanded };
}

const Click = struct {
    disabled: Source(bool),
    handler: ?ui.Handler(void),
    owner: *reactive.SignalOwner,
    fn run(self: @This()) void {
        if (self.disabled.peek()) return;
        self.owner.beginBatch();
        defer self.owner.endBatch();
        ui.on.fire(self.handler, .{});
    }
};

fn mountPressable(props: PressableProps, scope: *Scope, cx: *Cx) anyerror!v.ViewParts {
    const focusable = try scope.derive(bool, .{ .d = props.disabled }, struct {
        fn f(c: anytype) bool {
            return !c.d.get();
        }
    }.f);
    const semantics = try scope.derive(core.A11yProps, .{ .name = props.a11y_label, .description = props.a11y_description, .d = props.disabled, .s = props.selected, .e = props.expanded }, struct {
        fn f(c: anytype) core.A11yProps {
            return a11yOf(c.name.get(), c.description.get(), c.d.get(), c.s.get(), c.e.get());
        }
    }.f);
    const on_click = try ui.on.bind(scope, Click{ .disabled = props.disabled, .handler = props.on_click, .owner = scope.owner }, Click.run);
    const root = try v.render(scope, cx, v.row(.{
        .tag = .button,
        .style = Root.of(.{}).merge(props.look),
        .state = .{ .disabled = props.disabled, .selected = props.selected, .expanded = props.expanded, .invalid = false },
        .focusable = focusable,
        .focus_ring = props.focus_ring,
        .on_click = on_click,
        .a11y = semantics,
    }, .{}));
    root.meta.ownership.meta.component_name = "Pressable";
    return .{ .root = root, .slot = root };
}

// ===== Tests =====

const testing = std.testing;

const Env = struct {
    cx: *Cx,
    scope: *Scope,
    fn init() !Env {
        const cx = try Cx.init(testing.allocator, testing.io);
        errdefer cx.deinit();
        return .{ .cx = cx, .scope = try Scope.init(testing.allocator, null, cx.owner) };
    }
    fn deinit(e: Env, root: *Node) void {
        e.scope.dispose();
        e.cx.freeNode(root);
        e.cx.deinit();
    }
};

const Counter = struct {
    n: usize = 0,
    fn hit(self: *Counter) void {
        self.n += 1;
    }
};

fn findTestId(n: *Node, id: []const u8) ?*Node {
    if (n.meta.ownership.meta.test_id) |t| if (std.mem.eql(u8, t, id)) return n;
    for (n.children.items) |c| if (findTestId(c, id)) |r| return r;
    return null;
}

test "Pressable: children are the content of the clickable, focusable button root" {
    const env = try Env.init();
    var counter: Counter = .{};
    const root = try v.render(env.scope, env.cx, v.col(.{}, .{
        v.attrs(.{ .test_id = "row" }, v.with(Pressable(.{ .on_click = env.cx.on(Counter, &counter, Counter.hit), .a11y_label = "General" }), .{
            v.box(.{ .style = .{ .width = .{ .px = 16 }, .height = .{ .px = 16 } } }, .{}),
            v.text(.{}, "General"),
            v.text(.{}, "Window, startup"),
        })),
    }));
    defer env.deinit(root);
    const row = findTestId(root, "row").?;
    // test_id on the clickable root, the children directly under it (no wrapper, no anchor).
    try testing.expectEqual(core.ElementTag.button, row.tag);
    try testing.expectEqualStrings("Pressable", row.meta.ownership.meta.component_name.?);
    try testing.expectEqual(@as(usize, 3), row.children.items.len);
    try testing.expectEqualStrings("General", row.children.items[1].getText().?.content);
    try testing.expectEqual(core.A11yRole.button, row.behavior.interaction.a11y.?.role);
    try testing.expectEqualStrings("General", row.behavior.interaction.a11y.?.label.?);
    // No description unless one is given.
    try testing.expect(row.behavior.interaction.a11y.?.description == null);
    try testing.expect(row.behavior.interaction.focusable);
    // No look of its own: no padding / gap / background; a row with centered cross axis.
    try testing.expectEqual(@as(f32, 0), row.style.gap);
    try testing.expectEqual(@as(f32, 0), row.style.padding.left);
    try testing.expectEqual(core.Direction.row, row.style.direction);
    try testing.expectEqual(core.CursorShape.pointer, row.style.cursor);
    {
        const h = row.behavior.events.on_click.?;
        h.callback(h.context);
    }
    try testing.expectEqual(@as(usize, 1), counter.n);
}

test "Pressable: a11y_description follows its source" {
    const env = try Env.init();
    var counter: Counter = .{};
    const details = try env.scope.createSignal([]const u8, "alpha · 200K");
    const root = try v.render(env.scope, env.cx, v.col(.{}, .{
        v.attrs(.{ .test_id = "row" }, v.with(Pressable(.{ .on_click = env.cx.on(Counter, &counter, Counter.hit), .a11y_label = "alpha", .a11y_description = details }), .{v.text(.{}, "alpha")})),
    }));
    defer env.deinit(root);
    const row = findTestId(root, "row").?;
    try testing.expectEqualStrings("alpha · 200K", row.behavior.interaction.a11y.?.description.?);
    details.set("alpha · 32K");
    try testing.expectEqualStrings("alpha · 32K", row.behavior.interaction.a11y.?.description.?);
}

test "Pressable: disabled suppresses click, leaves the Tab order and shows not-allowed; reactive" {
    const env = try Env.init();
    var counter: Counter = .{};
    const off = try env.scope.createSignal(bool, true);
    const selected = try env.scope.createSignal(bool, false);
    const root = try v.render(env.scope, env.cx, v.with(Pressable(.{ .on_click = env.cx.on(Counter, &counter, Counter.hit), .disabled = off, .selected = selected }), .{v.text(.{}, "x")}));
    defer env.deinit(root);
    {
        const h = root.behavior.events.on_click.?;
        h.callback(h.context);
    }
    try testing.expectEqual(@as(usize, 0), counter.n);
    try testing.expect(!root.behavior.interaction.focusable);
    try testing.expectEqual(core.CursorShape.not_allowed, root.style.cursor);
    try testing.expect(root.behavior.interaction.a11y.?.disabled);
    off.set(false);
    selected.set(true);
    {
        const h = root.behavior.events.on_click.?;
        h.callback(h.context);
    }
    try testing.expectEqual(@as(usize, 1), counter.n);
    try testing.expect(root.behavior.interaction.focusable);
    try testing.expectEqual(core.CursorShape.pointer, root.style.cursor);
    try testing.expect(root.behavior.interaction.a11y.?.selected);
}

test "Pressable: a YSS look resolves per state on the root and follows the theme" {
    const env = try Env.init();
    const selected = try env.scope.createSignal(bool, false);
    const Row = ui.css(.{ .background = ui.tokenRef(.color, "bg-secondary"), .padding = .{ .left = 8, .right = 8 }, ._selected = .{ .background = ui.tokenRef(.color, "accent") }, ._hover = .{ .background = ui.tokenRef(.color, "bg-hover") } });
    env.cx.setTheme(&core.theme.light);
    const root = try v.render(env.scope, env.cx, v.with(Pressable(.{ .selected = selected, .look = Row }), .{v.text(.{}, "x")}));
    defer env.deinit(root);
    const light = core.theme.light.tokens.color;
    try testing.expectEqual(light.bg_secondary, root.getBackground());
    try testing.expectEqual(@as(f32, 8), root.style.padding.left);
    selected.set(true);
    try testing.expectEqual(light.accent, root.getBackground());
    // Theme switch: the look re-resolves with no caller involvement.
    env.cx.setTheme(&core.theme.dark);
    try testing.expectEqual(core.theme.dark.tokens.color.accent, root.getBackground());
    selected.set(false);
    try testing.expectEqual(core.theme.dark.tokens.color.bg_secondary, root.getBackground());
    try testing.expect(!core.Color.eql(light.bg_secondary, core.theme.dark.tokens.color.bg_secondary));
}

test "Pressable: cursor defaults sit under the look (base cursor changes the enabled one, :disabled the disabled one)" {
    const env = try Env.init();
    const off = try env.scope.createSignal(bool, false);
    const Text = ui.css(.{ .cursor = .text });
    const Both = ui.css(.{ .cursor = .text, ._disabled = .{ .cursor = .default } });
    const root = try v.render(env.scope, env.cx, v.col(.{}, .{
        v.attrs(.{ .test_id = "a" }, v.with(Pressable(.{ .disabled = off, .look = Text }), .{v.text(.{}, "a")})),
        v.attrs(.{ .test_id = "b" }, v.with(Pressable(.{ .disabled = off, .look = Both }), .{v.text(.{}, "b")})),
        v.attrs(.{ .test_id = "c" }, v.with(Pressable(.{ .disabled = off }), .{v.text(.{}, "c")})),
    }));
    defer env.deinit(root);
    const a = findTestId(root, "a").?;
    const b = findTestId(root, "b").?;
    const plain = findTestId(root, "c").?;
    try testing.expectEqual(core.CursorShape.text, a.style.cursor);
    try testing.expectEqual(core.CursorShape.text, b.style.cursor);
    try testing.expectEqual(core.CursorShape.pointer, plain.style.cursor);
    off.set(true);
    try testing.expectEqual(core.CursorShape.not_allowed, a.style.cursor);
    try testing.expectEqual(core.CursorShape.default, b.style.cursor);
    try testing.expectEqual(core.CursorShape.not_allowed, plain.style.cursor);
}

test "Pressable: a look source switching to a look without a field takes that field back" {
    const env = try Env.init();
    const Filled = ui.css(.{ .background = ui.tokenRef(.color, "accent") });
    const Bare = ui.css(.{ .padding = .{ .left = 4 } });
    const look = try env.scope.createSignal(v.Look, v.Look.from(Filled));
    const root = try v.render(env.scope, env.cx, v.with(Pressable(.{ .look = look }), .{v.text(.{}, "x")}));
    defer env.deinit(root);
    try testing.expectEqual(env.cx.tokens.tokens.color.accent, root.getBackground());
    look.set(v.Look.from(Bare));
    try testing.expectEqual(@as(f32, 0), root.getBackground().a);
    try testing.expectEqual(@as(f32, 4), root.style.padding.left);
}

test "Pressable: OOM sweep" {
    try @import("../oom_sweep.zig").sweepMount("pressable", struct {
        fn run(scope: *Scope, cx: *Cx) anyerror!?*Node {
            return try v.render(scope, cx, v.with(Pressable(.{ .a11y_label = "x" }), .{ v.text(.{}, "a"), v.text(.{}, "b") }));
        }
    }.run);
}
